var e=JSON.parse(`"<h4>Сплавы медно-цинковые (латуни) литейные. Марки (ГОСТ 17711-93)</h4>\\n<p><i>Введен в действие с 01.01.95 постановлением Комитета Российской Федерации по стандартизации, метрологии и сертификации от 02.06.94 № 160; взамен ГОСТ 17711-80. Переиздание. Январь 2002 г.</i></p>\\n<p>Стандарт устанавливает марки медно-цинковых сплавов (латуней) в отливках. Марки и химический состав латуней должны соответствовать требованиям таблицы 1; механические свойства — таблицы 2.</p>\\n<p>Химический состав определяют по ГОСТ 1652.1 — ГОСТ 1652.13; допускается применять другие методы, обеспечивающие точность не ниже указанных стандартов. При разногласиях в оценке химического состава определение проводят по ГОСТ 1652.1 — ГОСТ 1652.13.</p>\\n<p>Механические свойства определяют на отдельно отлитых образцах или на образцах из отдельно отлитых проб; диаметр рабочей части образцов 10 мм, расчетная длина 50 мм. Способ литья образцов и проб должен соответствовать способу изготовления отливок; для литья под давлением и центробежного литья допускается заливка проб в кокиль. Испытание на растяжение — по ГОСТ 1497, твердость по Бринеллю — по ГОСТ 9012.</p>\\n<p><b>Таблица 1 — Марки и химический состав медно-цинковых сплавов (латуней)</b></p>\\n<div class=\\"hb-table\\"><table>\\n<thead>\\n<tr><th rowspan=\\"3\\">Наименование сплава</th><th rowspan=\\"3\\">Марка сплава</th><th colspan=\\"18\\">Химический состав, %</th></tr>\\n<tr><th colspan=\\"8\\">основных компонентов</th><th colspan=\\"10\\">примесей, не более</th></tr>\\n<tr><th>медь</th><th>алюминий</th><th>железо</th><th>марганец</th><th>кремний</th><th>олово</th><th>свинец</th><th>цинк</th><th>свинца</th><th>кремния</th><th>олова</th><th>сурьмы</th><th>марганца</th><th>железа</th><th>алюминия</th><th>фосфора</th><th>никеля</th><th>всего</th></tr>\\n</thead>\\n<tbody>\\n<tr><td>Латунь свинцовая</td><td>ЛЦ40С</td><td>57,0—<br>61,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,8—2,0</td><td>—</td><td>—</td><td>0,3</td><td>0,5</td><td>0,05</td><td>0,5</td><td>0,8</td><td>0,5</td><td>—</td><td>1,0</td><td>2,0</td></tr>\\n<tr><td>Латунь свинцовая</td><td>ЛЦ40Сд</td><td>58,0—<br>61,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,8—2,0</td><td>—</td><td>—</td><td>0,2</td><td>0,3</td><td>0,05</td><td>0,2</td><td>0,5</td><td>0,2</td><td>—</td><td>1,0</td><td>1,5</td></tr>\\n<tr><td>Латунь марганцовая</td><td>ЛЦ40Мц1,5</td><td>57,0—<br>60,0</td><td>—</td><td>—</td><td>1,0—2,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,7</td><td>0,1</td><td>0,5</td><td>0,1</td><td>—</td><td>1,5</td><td>—</td><td>0,03</td><td>1,0</td><td>2,0</td></tr>\\n<tr><td>Латунь марганцово-железная</td><td>ЛЦ40Мц3Ж</td><td>53,0—<br>58,0</td><td>—</td><td>0,5—1,5</td><td>3,0—4,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,5</td><td>0,2</td><td>0,5</td><td>0,1</td><td>—</td><td>—</td><td>0,6</td><td>0,05</td><td>0,5</td><td>1,7</td></tr>\\n<tr><td>Латунь марганцово-алюминиевая</td><td>ЛЦ40Мц3А</td><td>55,0—<br>58,5</td><td>0,5—1,5</td><td>—</td><td>2,5—3,5</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,2</td><td>0,2</td><td>0,5</td><td>0,05</td><td>—</td><td>1,0</td><td>—</td><td>0,03</td><td>1,0</td><td>1,5</td></tr>\\n<tr><td>Латунь марганцово-свинцовая</td><td>ЛЦ38Мц2С2</td><td>57,0—<br>60,0</td><td>—</td><td>—</td><td>1,5—2,5</td><td>—</td><td>—</td><td>1,5—2,5</td><td>—</td><td>—</td><td>0,4</td><td>0,5</td><td>0,1</td><td>—</td><td>0,8</td><td>0,8</td><td>0,05</td><td>1,0</td><td>2,2</td></tr>\\n<tr><td>Латунь марганцово-свинцово-кремнистая</td><td>ЛЦ37Мц2С2К</td><td>57—<br>60</td><td>—</td><td>—</td><td>1,5—2,5</td><td>0,5—1,3</td><td>—</td><td>1,5—3,0</td><td>—</td><td>As<br>0,05</td><td>Bi<br>0,01</td><td>0,6</td><td>0,1</td><td>—</td><td>0,7</td><td>0,7</td><td>0,1</td><td>1,0</td><td>1,7</td></tr>\\n<tr><td>Латунь алюминиевая</td><td>ЛЦ30А3</td><td>66,0—<br>68,0</td><td>2,0—3,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,7</td><td>0,3</td><td>0,7</td><td>0,1</td><td>0,5</td><td>0,8</td><td>—</td><td>0,05</td><td>0,3</td><td>2,6</td></tr>\\n<tr><td>Латунь оловянно-свинцовая</td><td>ЛЦ25С2</td><td>70,0—<br>75,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,5—1,5</td><td>1,0—3,0</td><td>—</td><td>—</td><td>0,5</td><td>—</td><td>0,2</td><td>0,5</td><td>0,7</td><td>0,3</td><td>—</td><td>1,0</td><td>1,5</td></tr>\\n<tr><td>Латунь алюминиево-железо-марганцовая</td><td>ЛЦ23А6Ж3Мц2</td><td>64,0—<br>68,0</td><td>4,0—7,0</td><td>2,0—4,0</td><td>1,5—3,0</td><td>—</td><td>—</td><td>—</td><td>—</td><td>0,7</td><td>0,3</td><td>0,7</td><td>0,1</td><td>—</td><td>—</td><td>—</td><td>—</td><td>1,0</td><td>1,8</td></tr>\\n<tr><td>Латунь кремнистая</td><td>ЛЦ16К4</td><td>78,0—<br>81,0</td><td>—</td><td>—</td><td>—</td><td>3,0—4,5</td><td>—</td><td>—</td><td>—</td><td>0,5</td><td>—</td><td>0,3</td><td>0,1</td><td>0,8</td><td>0,6</td><td>0,04</td><td>0,1</td><td>0,2</td><td>2,5</td></tr>\\n<tr><td>Латунь кремнисто-свинцовая</td><td>ЛЦ14К3С3</td><td>77—81</td><td>—</td><td>—</td><td>—</td><td>2,5—4,5</td><td>—</td><td>2,0—4,0</td><td>—</td><td>—</td><td>—</td><td>0,3</td><td>0,1</td><td>1,0</td><td>0,6</td><td>0,3</td><td>—</td><td>0,2</td><td>2,3</td></tr>\\n</tbody>\\n</table></div>\\n<p><b>Таблица 2 — Механические свойства латуней</b></p>\\n<div class=\\"hb-table\\"><table>\\n<thead>\\n<tr><th rowspan=\\"2\\">Марка латуни</th><th rowspan=\\"2\\">Способ литья</th><th colspan=\\"3\\">не менее</th><th rowspan=\\"2\\">Примерное назначение литья</th></tr>\\n<tr><th>Временное сопротивление разрыву, Н/мм² (кгс/мм²)</th><th>Относительное удлинение δ5, %</th><th>Твердость по Бринеллю, НВ</th></tr>\\n</thead>\\n<tbody>\\n<tr><td rowspan=\\"2\\">ЛЦ40С</td><td>П</td><td>215 (22)</td><td>12</td><td>70</td><td rowspan=\\"2\\">Для литья арматуры, втулок и сепараторов шариковых и роликовых подшипников</td></tr>\\n<tr><td>К, Ц</td><td>215 (22)</td><td>20</td><td>80</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ40Сд</td><td>Д</td><td>196 (20)</td><td>6</td><td>70</td><td rowspan=\\"2\\">Для литья под давлением арматуры (втулки, тройники, переходники), сепараторов подшипников, работающих в среде воздуха или пресной воды</td></tr>\\n<tr><td>К</td><td>264 (27)</td><td>18</td><td>100</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ40Мц1,5</td><td>П</td><td>372 (38)</td><td>20</td><td>100</td><td rowspan=\\"2\\">Для изготовления деталей простой конфигурации, работающих при ударных нагрузках, а также деталей узлов трения, работающих в условиях спокойной нагрузки при температурах не выше 60 °С</td></tr>\\n<tr><td>К, Ц</td><td>392 (40)</td><td>20</td><td>110</td></tr>\\n<tr><td rowspan=\\"3\\">ЛЦ40Мц3Ж</td><td>П</td><td>441 (45)</td><td>18</td><td>90</td><td rowspan=\\"3\\">Для изготовления несложных по конфигурации деталей ответственного назначения и арматуры морского судостроения, работающих при температуре до 300 °С; массивных деталей, гребных винтов и их лопастей для тропиков</td></tr>\\n<tr><td>К</td><td>490 (50)</td><td>10</td><td>100</td></tr>\\n<tr><td>Д</td><td>392 (40)</td><td>—</td><td>—</td></tr>\\n<tr><td rowspan=\\"1\\">ЛЦ40Мц3А</td><td>К, Ц</td><td>441 (45)</td><td>15</td><td>115</td><td rowspan=\\"1\\">Для изготовления деталей несложной конфигурации</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ38Мц2С2</td><td>П</td><td>245 (25)</td><td>15</td><td>80</td><td rowspan=\\"2\\">Для изготовления конструкционных деталей и аппаратуры для судов; антифрикционных деталей несложной конфигурации (втулки, вкладыши, ползуны, арматура вагонных подшипников)</td></tr>\\n<tr><td>К</td><td>343 (35)</td><td>10</td><td>85</td></tr>\\n<tr><td rowspan=\\"1\\">ЛЦ37Мц2С2К</td><td>К</td><td>343 (35)</td><td>2</td><td>110</td><td rowspan=\\"1\\">Антифрикционные детали, арматура</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ30А3</td><td>П</td><td>294 (30)</td><td>12</td><td>80</td><td rowspan=\\"2\\">Для изготовления коррозионно-стойких деталей, применяемых в судостроении и машиностроении</td></tr>\\n<tr><td>К</td><td>392 (40)</td><td>15</td><td>90</td></tr>\\n<tr><td rowspan=\\"1\\">ЛЦ25С2</td><td>П</td><td>146 (15)</td><td>8</td><td>60</td><td rowspan=\\"1\\">Для изготовления штуцеров гидросистем автомобилей</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ23А6Ж3Мц2</td><td>П</td><td>686 (70)</td><td>7</td><td>160</td><td rowspan=\\"2\\">Для изготовления ответственных деталей, работающих при высоких удельных и знакопеременных нагрузках, при изгибе, а также антифрикционных деталей (нажимные винты, гайки нажимных винтов прокатных станов, венцы червячных колес, втулки и др. детали)</td></tr>\\n<tr><td>К, П</td><td>705 (72)</td><td>7</td><td>165</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ16К4</td><td>П</td><td>294 (30)</td><td>15</td><td>100</td><td rowspan=\\"2\\">Для изготовления сложных по конфигурации деталей приборов и арматуры, работающих при температуре до 250 °С и подвергающихся гидровоздушным испытаниям; деталей, работающих в среде морской воды, при условии обеспечения протекторной защиты (шестерни, детали узлов трения и др.)</td></tr>\\n<tr><td>К</td><td>343 (35)</td><td>15</td><td>110</td></tr>\\n<tr><td rowspan=\\"2\\">ЛЦ14К3С3</td><td>К</td><td>294 (30)</td><td>15</td><td>100</td><td rowspan=\\"2\\">Для изготовления подшипников, втулок</td></tr>\\n<tr><td>П</td><td>245 (25)</td><td>7</td><td>90</td></tr>\\n</tbody>\\n</table></div>\\n<div class=\\"hb-note\\"><b>Примечание к таблице 2.</b> Условные обозначения способов литья: П — литье в песчаную литейную форму; К — кокильное литье; Д — литье под давлением; Ц — центробежное литье.</div>\\n<div class=\\"hb-note\\"><b>Примечания к таблице 1.</b> 1. Массовая доля никеля в латунях допускается за счет меди и в сумму примесей не входит. 2. По требованию потребителя массовая доля свинца в латуни марки ЛЦ40Сд допускается 1,2—2,0 %. 3. В латуни марки ЛЦ16К4 по согласованию изготовителя с потребителем допускается массовая доля алюминия до 0,1 % при изготовлении деталей, не требующих гидравлической плотности. 4. В латуни марки ЛЦ40Мц3Ж, применяемой для отливки гребных винтов, массовая доля меди должна быть 55—58 %, алюминия — не более 0,8 %, свинца — не более 0,3 %. 5. Примеси, не указанные в табл. 1, учитываются в общей сумме примесей. 6. По согласованию изготовителя с потребителем в латуни марки ЛЦ38Мц2С2 массовая доля свинца допускается 1,2—2,0 %.</div>\\n<div class=\\"hb-note\\"><b>Обозначения в таблице 1.</b> В графах «свинца» и «кремния» для марки ЛЦ37Мц2С2К вместо массовой доли свинца и кремния нормируются мышьяк (As) и висмут (Bi): As — не более 0,05 %, Bi — не более 0,01 %; в общей сумме примесей эти значения учтены.</div>"`);export{e as default};